package dev.chieppa.ease.build.licenses

/** The `NOTICE` file: Ease's own notice, then every shipped dependency and its license. */
object Notice {
  fun render(header: String, shipped: List<ShippedLicense>): String = buildString {
    append(header.replace("\r\n", "\n").trimEnd())
    append("\n\nThird-party software\n\n")
    append(
      "Ease ships with these libraries, each under its own license. This list is generated by\n"
    )
    append("./gradlew generateNotice.\n\n")
    val width = shipped.maxOfOrNull { coordinates(it).length } ?: 0
    shipped.forEach { append("${coordinates(it).padEnd(width)}  ${it.license ?: "unknown"}\n") }
  }

  /** Whether [current], the file as it stands, matches [expected] apart from line endings. */
  fun isCurrent(current: String, expected: String): Boolean =
    current.replace("\r\n", "\n") == expected

  private fun coordinates(shipped: ShippedLicense) = "${shipped.module}:${shipped.version}"
}
